import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type LinksBelowProps = Record<string, any>;

const LinksBelow: React.FC<LinksBelowProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  text = "Links Below",
  textColor = "#ffffff",
  arrowColor = "#ffffff",
  arrowCount = 3,
  arrowSize = 150,
  gap = 80,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive calculations
  const baseSize = Math.min(width, height);
  const fontSize = baseSize * 0.15;

  // Text Animation
  const textScale = spring({
    fps,
    frame: frame,
    config: { damping: 12, mass: 0.8 },
  });

  const textOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  const textY = interpolate(frame, [0, 20], [50, 0], {
    extrapolateRight: "clamp",
  });

  // Array to map arrows
  const arrowsArray = new Array(Math.round(arrowCount)).fill(0);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: "5%",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: `${gap}px`,
        }}
      >
        {/* Animated Text Container */}
        <div
          style={{
            fontSize: `${fontSize}px`,
            fontWeight: 900,
            color: textColor,
            opacity: textOpacity,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            textAlign: "center",
            transform: `scale(${textScale}) translateY(${textY}px)`,
            transition: "none",
          }}
        >
          {text}
        </div>

        {/* Animated Arrows Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            gap: `${gap * 0.8}px`,
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {arrowsArray.map((_, i) => {
            const delay = 10 + i * 5;
            
            // Entrance pop
            const arrowScale = spring({
              fps,
              frame: frame - delay,
              config: { damping: 10, mass: 0.8 },
            });

            // Opacity fade in
            const arrowOpacity = interpolate(
              frame - delay,
              [0, 10],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // Looping bounce effect after appearance
            // Using frame logic to calculate a sine wave offset
            const isVisible = frame >= delay;
            const bounceOffset = isVisible
              ? Math.sin((frame - delay) * 0.15) * (baseSize * 0.02)
              : 0;

            return (
              <div
                key={i}
                style={{
                  width: `${arrowSize}px`,
                  height: `${arrowSize}px`,
                  opacity: arrowOpacity,
                  transform: `scale(${arrowScale}) translateY(${bounceOffset}px)`,
                  transition: "none",
                  color: arrowColor,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {/* Chunky Filled Arrow SVG */}
                <svg
                  viewBox="0 0 24 24"
                  fill="currentColor"
                  style={{ width: "100%", height: "100%" }}
                >
                  <path d="M12 21l-9-9h5v-9h8v9h5l-9 9z" />
                </svg>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LinksBelow;